const EXTRA_DETAILS = {
 l1:['Серверді бағалағанда қызмет түрін, бір уақытта келетін сұрауларды, қолжетімділік талабын және деректердің маңызын анықта. Физикалық сервер бірнеше қызметті іске қоса алады, бірақ оларды оқшаулау қауіпсіздік пен басқаруды жеңілдетуі мүмкін.','Практика: браузерден бір веб-сайт ашқанда клиент, DNS, желі, веб-сервер және деректер базасы қалай әрекеттесетінін сызбаға түсір.','Жиі қате: «сервер міндетті түрде үлкен компьютер» деп ойлау. Сервердің негізгі анықтамасы оның желіге қызмет ұсынуымен байланысты.'],
 l2:['Жүйеде веб, файл, каталог, қолданба, пошта және деректер базасы қызметтері бөлек болуы немесе ортақ хостта іске қосылуы мүмкін. Бірнеше қызметті біріктіру құнын азайтады, ал бөлу ақаудың таралуын шектеуі мүмкін.','Практика: колледждің оқу порталын жобалап, веб-сервер, деректер базасы және файл сақтау қызметтерінің міндетін жеке-жеке белгіле.','Жиі қате: сервер түрін жабдықтың пішіні бойынша емес, оның орындайтын міндеті бойынша ажырату керек.'],
 l3:['Сұрау-жауап ағыны көбіне DNS атауды шешуден, TCP байланысынан, TLS келісімінен (HTTPS), HTTP сұраудан және сервер жауабынан тұрады. Қолданбаның артында деректер базасы немесе басқа API болуы мүмкін.','Практика: клиент → веб-сервер → қолданба → деректер базасы → жауап жолын көрсетіп, әр кезеңде қандай ақау болуы мүмкін екенін жаз.','Жиі қате: браузер бетті көрсетпесе, бірден сервер өшті деп ойлама; DNS, TLS сертификаты, желі, қолданба және база ақаулары да ықпал етеді.'],
 l4:['CPU үшін ядро саны, бір ағынның жылдамдығы, кэш, жад өткізу қабілеті және нақты қолданба маңызды. Виртуализация мен көп сұраулы веб-жүктемеде параллелизм пайдалы, бірақ өнімділікті benchmark және мониторингпен бағалау керек.','Практика: CPU қолдануы тұрақты 95% болса, уақыт аралығын, процесс тізімін және сұрау көлемін тексеруге арналған қысқа жоспар құрастыр.','Жиі қате: жиілігі ең жоғары процессор барлық серверлік есепке ең жақсы болады деу.'],
 l5:['RAM тапшылығы swap/pagefile қолдануын, ұзақ жауап уақытын немесе процестің тоқтауын туғызуы мүмкін. Серверде жад арналарын дұрыс орналастыру және ECC қолдауы аппараттық конфигурациямен тексеріледі.','Практика: жад мониторингінен қолданыстағы көлемді, бос көлемді, swap/pagefile және үрдісті бақылайтын 3 метриканы ата.','Жиі қате: RAM-ды тұрақты файл сақтау құрылғысы деп есептеу; қуат өшкенде оның уақытша мазмұны сақталмайды.'],
 l6:['Аналық тақшадағы процессор ұясы, чипсет, RAM буыны, PCIe слоттары, басқару контроллері және форм-фактор өзара үйлесуі керек. Қуаттың резервтелуі мен ауа ағыны сервер жұмысында температура және тоқтап қалу тәуекеліне әсер етеді.','Практика: сервер бөлмесіндегі температура шектен асса, желдеткіш, ауа кірісі/шығысы, шаң, жүктеме және журналды тексеретін жоспар жаса.','Жиі қате: компоненттердің жеке-жеке үйлесімді болуы толық жүйенің де үйлесімді екенін автоматты білдіреді деп ойлау.'],
 l7:['HDD сыйымдылық пен құн жағынан архивке тиімді болуы мүмкін; SSD кездейсоқ оқу/жазуды жылдамдатады; NVMe әдетте PCIe арқылы төмен кідіріс пен жоғары өткізгіштік береді. Төзімділік, температура, интерфейс және жұмыс жүктемесі де ескеріледі.','Практика: архивтік файл сервері мен транзакциялық деректер базасына бөлек сақтау стратегиясын таңда да себебін негізде.','Жиі қате: тек «оқу жылдамдығын» қарап, кідіріс, жазу төзімділігі, сыйымдылық пен резервтік көшіруді ұмыту.'],
 l8:['RAID 0 төзімділік бермейді; RAID 1 көшірме жасайды; RAID 5 паритетті пайдаланады; RAID 10 өнімділік пен айна режимін біріктіреді. Қалпына келтіру уақыты, диск көлемі, контроллер және қайта құру кезіндегі тәуекел де маңызды.','Практика: төрт дискісі бар жүйеге RAID 10 пен RAID 5 арасындағы таңдау жасап, сыйымдылық және ақауға төзімділік тұрғысынан түсіндір.','Жиі қате: RAID-ті резервтік көшірмемен шатастыру. RAID файлдың кездейсоқ өшірілуінен немесе ransomware-ден жалғыз өзі қорғамайды.'],
 l9:['Backup саясаты деректердің маңызын, көшірме жиілігін, сақталу мерзімін, шифрлауды және қалпына келтіру уақытын анықтауы керек. Immutable/offline көшірме кей ransomware шабуылдарының әсерін азайтуы мүмкін.','Практика: оқу порталындағы деректер базасына арналған backup күнтізбесін құрастыр және ай сайын restore-test қалай жасалатынын жаз.','Жиі қате: көшірме тапсырмасы «сәтті» болғанын жеткілікті деп санау; қалпына келтіру сынағы да міндетті.'],
 l10:['Коммутатор MAC кестесі бойынша жергілікті Ethernet кадрларын таратады; маршрутизатор IP бағыттау кестесін пайдаланады. VLAN арқылы желіні логикалық бөлу, ал ACL/Firewall арқылы трафикке ереже қоюға болады.','Практика: білім алушылар, оқытушылар және серверлер үшін үш VLAN сызбасын құрып, олардың арасында қандай трафикке рұқсат берілетінін белгіле.','Жиі қате: коммутатор мен маршрутизатордың міндетін бірдей деп есептеу. Қазіргі құрылғылар функцияларды біріктірсе де, логикалық айырмашылық қалады.'],
 l11:['IP желілік интерфейсті мекенжайлайды; DNS атаулар мен басқа жазбаларды табуға көмектеседі; DHCP желі параметрлерін таратады. Диагностикада IP, маска, шлюз, DNS сервері және жалға алу мерзімі тексеріледі.','Практика: компьютер интернетке қосылмаса, IP параметрлерін, шлюзді, DNS шешімін және сыртқы мекенжайға қолжетімділікті қандай ретпен тексеретініңді жаз.','Жиі қате: домен ашылмағанда міндетті түрде интернет жоқ деп ойлау; DNS қателігі де себеп болуы мүмкін.'],
 l12:['Өткізу қабілеті, нақты throughput, кідіріс, jitter және пакет жоғалту әртүрлі қасиеттерді өлшейді. Бейнеқоңырау төмен кідіріске, ал үлкен файл көшіру жоғары throughput-қа көбірек тәуелді болуы мүмкін.','Практика: ping нәтижесінде кідіріс қалыпты, бірақ файл көшіру баяу болса, кабель, порт жылдамдығы, жүктеме, диск және сервер CPU себептерін қарастыр.','Жиі қате: порттың номинал жылдамдығын қолданба алатын нақты жылдамдықпен теңестіру.'],
 l13:['Гипервизор виртуалды машиналар арасында CPU, жад, сақтау және желі ресурстарын бөледі. Type 1 гипервизор аппараттық деңгейге жақын іске қосылады; Type 2 хост операциялық жүйесінің үстінде жұмыс істейді.','Практика: бір серверде тест ортасы мен production қызметін бөлудің виртуалды машиналар арқылы қандай пайдасы барын түсіндір.','Жиі қате: виртуалды машиналарда физикалық хостпен ортақ ресурстар мен ақау домені барын ұмыту.'],
 l14:['Контейнер қосымшаны тәуелділіктерімен бірге оқшаулайды және көбіне хост ядросын бөліседі; VM жеке қонақ операциялық жүйесін іске қосады. Контейнердің жеңілдігі image жаңарту, құпия мәндер және желі конфигурациясын басқару міндетін жоймайды.','Практика: шағын веб-қызметті контейнерде іске қосқанда image, port, environment variables, persistent volume және health check тізімін жаса.','Жиі қате: контейнер ішінде сақталған дерек контейнер жойылған соң міндетті сақталады деп ойлау; тұрақты көлем бөлек жоспарланады.'],
 l15:['IaaS инфрақұрылымды, PaaS қолданба платформасын, SaaS дайын бағдарламалық қызметті ұсынады. Бұлттық қызмет таңдағанда баға, деректердің орналасуы, қолжетімділік, резервтік көшіру, сәйкестік пен vendor lock-in бағаланады.','Практика: білім алушыларға арналған оқу платформасына IaaS, PaaS немесе SaaS моделін таңдап, қызмет көрсетуші мен ұйым жауапкершілігін ажырат.','Жиі қате: бұлтта қауіпсіздік пен backup-қа жауапкершілік толықтай провайдерде деп ойлау. Ортақ жауапкершілік моделі қолданылады.'],
 l16:['Аутентификация — пайдаланушының кім екенін тексеру; авторизация — сол пайдаланушыға не істеуге рұқсат етілгенін анықтау. MFA бірнеше түрлі факторды қолданады; рөлдер мен ең аз артықшылық күнделікті қауіпсіздікті күшейтеді.','Практика: білім алушы, оқытушы және әкімші рөлдеріне рұқсат кестесін құрып, әр рөл тек қажетті әрекеттерді орындайтындай ереже ұсын.','Жиі қате: күшті парольдің өзі phishing, ортақ аккаунт немесе артық құқық мәселесін толық шешеді деп санау.'],
 l17:['Патчтар белгілі осалдықтарды түзетеді, бірақ оларды сынақтан өткізіп, өзгеріс терезесін жоспарлау керек. Firewall ережелері нақты қажеттілікке сүйеніп, default-deny қағидасы мүмкін болған жерде қолданылады. Антивирус/EDR мониторингі басқа қорғаныс қабаттарын толықтырады.','Практика: жаңарту алдында backup пен rollback жоспарын, ал кейін қызмет, журнал және негізгі транзакция тестін тексеретін чек-парақ жаса.','Жиі қате: «firewall қосулы» дегенді жеткілікті қауіпсіздік деп қабылдау; ережелер мен журналдар да тексеріледі.'],
 l18:['Журналда уақыт, қызмет, оқиға түрі және сұрау контексті көрінуі диагностикаға көмектеседі. Аудит дерегі қолжетімділікті бақылау үшін қажет, бірақ жеке мәліметті шамадан тыс жинамау және сақтау мерзімін белгілеу де маңызды.','Практика: бірнеше сәтсіз кіру әрекеті байқалса, дәлелді сақтап, қауіпсіздік тобына хабарлау, есептік жазбаны қорғау және оқиғаны құжаттау ретін ұсын.','Жиі қате: инцидент кезінде журналдарды өшіріп жіберу; бұл тергеуге қажет дәлелді жоғалтуы мүмкін.'],
 l19:['CPU utilization, жад қолданысы, диск кідірісі, IOPS, желі throughput және қате көрсеткіштері бірге қаралады. Бір ғана метрикаға сүйену мәселені дұрыс түсіндірмеуі мүмкін; уақыт аралығы және қалыпты базалық деңгей қажет.','Практика: сервер баяулағанда қай төрт метриканы салыстыратыныңды және әрқайсысы қандай гипотезаға әкелетінін жаз.','Жиі қате: alert-терді тым жиі жіберу немесе нақты қызмет әсерімен байланыстырмай қою.'],
 l20:['Диагностика симптомды анықтаудан басталады, содан кейін ықтимал себептер тексеріледі. Соңғы өзгерістер, журнал, метрикалар, желі күйі, тәуелді қызметтер және қайталайтын тест жүйелі түрде қаралады.','Практика: «сайт 502 қатесін береді» деген жағдайға 5 қадамдық тексеру тізбегін жаса: proxy, backend process, port, logs және dependency.','Жиі қате: дәлел жинамай бірнеше параметрді қатар өзгерту; бұл мәселені күрделендіріп, бастапқы себепті жасыруы мүмкін.'],
 l21:['SLA қызметтің қолжетімділігі, жауап беру уақыты және қолдау міндеттерін анықтай алады. Резервтеу сервер, қуат, желі және сақтау деңгейінде жоспарланып, бір ортақ failure domain қалдырмауға тырысады.','Практика: 99.9% қолжетімділік мақсаты бар оқу сервисіне резервтік желі, backup және оқиға туралы хабарлау жоспарын ұсын.','Жиі қате: барлық компонент резервтелгендей көрінгенімен, бір ортақ қуат көзі не деректер базасы жалғыз істен шығу нүктесі болып қалуы.'],
 l22:['Рэк ішіндегі ауа ағынын бөгемеу, салқын/ыстық дәлізді ұйымдастыру, кабельді таңбалау, температураны бақылау және физикалық кіруді шектеу қызмет көрсетуді жеңілдетеді. Дата-орталықта өртті анықтау мен электр қуатын резервтеу де жобаның бөлігі.','Практика: сервер бөлмесінің шағын жоспарында рэк, желілік жабдық, UPS, салқындату, кабель жолдары және кіру бақылауын белгіле.','Жиі қате: физикалық қолжетімділікті киберқауіпсіздіктен бөлек деп қарау; ашық рэк пен консольге қол жеткізу де қауіп тудырады.'],
 l23:['PUE деректер орталығының жалпы энергиясын IT жабдығы тұтынатын энергиямен салыстыратын метрика ретінде қолданылады; ол жалғыз экологиялық көрсеткіш емес. Қуат тұтынуы, салқындату, жабдықтың өмірлік циклі және жұмыстың пайдалы нәтижесі бірге қаралады.','Практика: мониторингте энергия тұтынуы артқанын байқасаң, IT жүктемесі, температура, салқындатқыштар және пайдаланылмайтын серверлерді тексеретін жоспар жаз.','Жиі қате: электрді аз жұмсау үшін салқындатуды өшіру; бұл сенімділік пен жабдыққа зиян келтіруі мүмкін.'],
 l24:['Өзгерістерді басқару, инцидент есебі, пароль/кілт саясаты, backup тексеруі және желі диаграммасы басқа мамандардың жүйені қауіпсіз қолдауына көмектеседі. Есеп фактіге сүйеніп, болжамды бөлек белгілеуі керек.','Практика: сервер конфигурациясын өзгерткеннен кейінгі қысқа change record үлгісін жаса: себеп, тәуекел, backup, сынақ, нәтиже және rollback.','Жиі қате: ИИ берген команданы тексермей өндірістік серверде іске қосу немесе құпия деректі сыртқы қызметке жіберу.'],
 l25:['ОЖ таңдауда жаңарту мерзімі, драйвер мен бағдарламалық үйлесімділік, құқықтарды басқару, мониторинг және қолдау мүмкіндігі бағаланады. Сынақ ортасы өндірістік ортадан бөлінгені дұрыс.','Практика: шағын веб-жобаға Linux серверін таңдайтын 3 себеп пен Windows Server орынды болуы мүмкін бір жағдайды жаз.','Жиі қате: операциялық жүйе таңдауды тек жеке ұнатуға сүйендіру; қолдау мен талаптарды да салыстыру қажет.'],
 l26:['Топ арқылы рұқсат беру басқаруды жеңілдетеді, ал нақты файлдық жүйеде оқу, жазу және орындау құқығы бөлек болуы мүмкін. Рұқсат мұрагерлігі мен ортақ папка саясатын түсіну кездейсоқ дерек ашылуының алдын алады.','Практика: «оқу материалдары», «бағалау нәтижелері» және «әкімшілік құжаттар» үшін әртүрлі рұқсат матрицасын құрастыр.','Жиі қате: мәселені шешу үшін барлық пайдаланушыға толық рұқсат беру. Құқықты қажетті минимуммен шекте.'],
 l27:['Қызметтің өз журналы және жүйелік журнал бірге қаралады. Қашықтан басқаруды тек рұқсат етілген желіден ұсыну, SSH кілтін қорғау және журналдарға уақыт синхрондау орнату аудит сапасын жақсартады.','Практика: тоқтаған веб-қызметті тексеруге күй, соңғы 50 журнал жолы, порт және HTTP жауабын тексеретін чек-парақ жаз.','Жиі қате: қызметті қайта іске қосып, симптомның себебі мен қайталануын тіркемей қою.'],
 l28:['HTTP әдістері мен кодтары интерфейс пен сервер арасындағы келісімді береді. TLS сертификаты жарамды болуы, доменге сәйкес келуі және жаңарту мерзімі бақылануы керек. Қателер беті құпия stack trace жарияламауы тиіс.','Практика: 200, 301, 400, 401, 403, 404, 429 және 500 кодтарының кез келген бесеуіне түсініктеме жаз.','Жиі қате: 200 жауабы бар болса, барлық бизнес-операция дұрыс орындалды деп бірден қорытындылау.'],
 l29:['Индекс іздеуге көмектіргенімен, қосымша сақтау мен жаңарту ресурсын талап етеді. Транзакция тұтастықты қолдайды; дерекке рұқсат, параметрленген SQL және шифрланған байланыс қауіпсіздіктің бөлігі.','Практика: білім алушы тест нәтижесін сақтау үшін Students, Lessons және Results кестелерінің өрістері мен байланысын жобала.','Жиі қате: пайдаланушы енгізген мәнді тікелей SQL жолына біріктіру; бұл SQL injection тәуекелін ұлғайтады.'],
 l30:['API келісімінде endpoint, HTTP әдісі, сұрау құрылымы, жауап коды және қате пішімі анықталады. Орта айнымалылары әр ортада бөлек болады; құпия кілтті клиенттік JavaScript-ке қоюға болмайды.','Практика: /api/progress endpoint-і үшін GET немесе PUT қолдану себебін, тексерілетін деректерді және ықтимал қате кодтарын жаз.','Жиі қате: локалды компьютерде істейтін жоба production-да да автоматты істейді деп ойлау; порт, env, база және deploy command тексеріледі.'],
 l31:['Теңгергіш кезекпен бөлу, ең аз байланыс немесе басқа алгоритмді қолдана алады. Сессияны серверде сақтайтын қосымшада sticky session не ортақ session store қажет болуы мүмкін.','Практика: бір backend health check-тен өтпесе, жаңа сұраулар қалай бағытталуы керек екенін түсіндір.','Жиі қате: тек backend санын арттыру жеткілікті деп санау; база, сессия және желі де масштабталуы қажет болуы мүмкін.'],
 l32:['Резерв түйіндер деректер мен конфигурация жағынан синхронды болуы керек. Автоматты ауысуда fencing, quorum және split-brain сияқты тәуекелдер қарастырылады; осы себеппен failover сынағы құжатталады.','Практика: негізгі веб-сервер тоқтаған сценарий үшін анықтау, ауысу, тексеру, хабарлау және кері қайту қадамдарын нөмірле.','Жиі қате: резервті бар деп санау, бірақ оны соңғы рет қашан сынағанын білмеу.'],
 l33:['Кэштеу жауап уақытын азайтады, бірақ өзгерген деректің қай кезде жаңаратынын жобалау қажет. Сыйымдылық жоспары маусымдық жүктемені, пайдаланушы өсімін және ресурстың қауіпсіз қорын ескереді.','Практика: 100 қолданушыдан 1000 қолданушыға өсу күтілсе, бірінші кезекте қандай метриканы жинайтыныңды және тік/көлденең масштабтауды қалай салыстыратыныңды жаз.','Жиі қате: масштабтауды мониторингсіз жасау және проблеманың нақты тар жерін анықтамау.'],
 l34:['Жобаның талаптарын кестеге түсір: мақсат, болжамды жүктеме, дерек көлемі, қолжетімділік, қауіпсіздік, бюджет және өсу жоспары. Әр таңдалған компонент нақты талапқа жауап беруі керек.','Практика: 300 білім алушыі бар порталға сервер архитектурасының қысқа сызбасын және ең маңызды үш тәуекелді ұсын.','Жиі қате: CPU мен RAM таңдауына көңіл бөліп, backup, журнал, желі және қауіпсіздікті ұмыту.'],
 l35:['Алдымен өзгеріс хронологиясын және әсер ауқымын анықта, кейін журнал мен метриканы салыстыр. Қауіпсіз диагностикада қайтымды кішкентай өзгерістер мен бақылаулы сынақ қолданылады.','Практика: «диск 95% толды» жағдайына деректерді жоғалтпай тексеру мен кеңейту қадамын жаса.','Жиі қате: журналдарды оқымай қызметті қайта-қайта қайта жүктеу немесе production дерегін жою.'],
 l36:['Сапалы есеп оқиғаны қайталауға және шешімнің нәтижесін бағалауға жететін контекст береді. Уақыт белдеуі, нақты өлшем және анонимделген журнал үзінділері пайдалы; құпия мәндер енгізілмейді.','Практика: бір ақау туралы 5 сөйлемдік есеп жаз: әсері, дәлел, ықтимал себеп, әрекет, кейінгі ұсыныс.','Жиі қате: нақты дәлел мен болжамды араластыру немесе орындалмаған жұмысты орындалды деп жазу.']
};
for (const lesson of allLessons) {
  lesson.videoSearch = VIDEO_SEARCH_TERMS[lesson.id] || `${lesson.title} server technical equipment tutorial`;
  lesson.extraDetails = EXTRA_DETAILS[lesson.id] || [
    `Бұл тақырыпты жүйелік деңгейде түсіну үшін оның басқа сервер компоненттерімен тәуелділігін қарастыр. ${lesson.content?.[0] || lesson.definition}`,
    `Практика: ${lesson.title} бойынша бақылауға болатын үш параметрді, ықтимал ақауды және оны тексеретін бір әдісті жаз.`,
    `Жиі қате: жеке компонентті ғана қарау. Нақты ортада жүктеме, қауіпсіздік, резерв және қызметтің бизнеске әсері бірге бағаланады.`
  ];
}

const STORAGE_KEY = 'serverlab-ai-progress-v1';
const todayISO = () => new Date().toISOString().slice(0,10);
const defaultState = () => ({profile:{name:'Білім алушы',group:'',goal:'basics'},results:{},attempts:[],xp:0,streak:0,lastActive:'',history:[],gameRewardDays:{},theme:'light'});
let state = loadState();
let activeLessonId = null;
let activeQuiz = null;
let chatBusy = false;
let currentFilter = 'all';
let currentGame = 'match';
let matchGame = null;
let flashIndex = 0;
let flashRevealed = false;
let quickGame = null;
let toastTimer = null;

function loadState(){try{const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return defaultState();const parsed=JSON.parse(raw);return {...defaultState(),...parsed,profile:{...defaultState().profile,...(parsed.profile||{})},results:parsed.results||{},attempts:parsed.attempts||[],history:parsed.history||[],gameRewardDays:parsed.gameRewardDays||{}};}catch{return defaultState();}}
function saveState(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(e){console.warn('Прогресті сақтау мүмкін болмады',e);}try{window.dispatchEvent(new CustomEvent('serverlab:state-saved',{detail:{state:JSON.parse(JSON.stringify(state))}}));}catch{}}
function escapeHTML(v){return String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function totalCompleted(){return allLessons.filter(l=>state.results[l.id]?.completed).length;}
function averageScore(){const attempts=state.attempts;if(!attempts.length)return null;return Math.round(attempts.reduce((s,a)=>s+a.percent,0)/attempts.length);}
function addHistory(title,detail,points=0,icon='✦'){state.history.unshift({title,detail,points,icon,at:new Date().toISOString()});state.history=state.history.slice(0,35);}
function markActivity(){const today=todayISO();if(state.lastActive!==today){const y=new Date();y.setDate(y.getDate()-1);const yesterday=y.toISOString().slice(0,10);state.streak=state.lastActive===yesterday?(state.streak||0)+1:1;state.lastActive=today;}saveState();}
function awardXP(amount){if(amount<=0)return;state.xp=(state.xp||0)+amount;}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2700);}
function displayName(){return state.profile.name||'Білім алушы';}
function pageTitle(page){return ({dashboard:'Басты бет',course:'Оқу курсы',serverlab:'Сервер зертханасы',lesson:'Сабақ',ai:'ИИ-тәлімгер',practice:'Тапсырмалар',games:'Оқу ойындары',progress:'Менің прогресім',about:'Жоба туралы',account:'Жеке кабинет',admin:'Әкімші панелі'})[page]||'Басты бет';}
function showPage(page){document.querySelectorAll('.page').forEach(el=>el.classList.remove('active'));const target=document.getElementById('page-'+page);if(target)target.classList.add('active');document.querySelectorAll('.nav-item[data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===page || (page==='lesson'&&el.dataset.page==='course')));document.getElementById('crumbCurrent').textContent=pageTitle(page);document.getElementById('sidebar').classList.remove('open');if(page==='dashboard')renderDashboard();if(page==='course')renderCourse();if(page==='serverlab')renderServerLab();if(page==='practice')renderPractice();if(page==='progress')renderProgress();if(page==='games')renderGame();if(page==='account')renderAccount();if(page==='admin')window.ServerLabAuth?.renderAdmin?.();window.scrollTo({top:0,behavior:'smooth'});}
function openLesson(id){const lesson=lessonMap[id];if(!lesson)return;activeLessonId=id;activeQuiz=null;renderLesson(lesson);showPage('lesson');document.getElementById('crumbCurrent').textContent='Сабақ';}
function renderTopProfile(){const name=displayName();document.getElementById('topName').textContent=name;document.getElementById('welcomeName').textContent=name;document.getElementById('topAvatar').textContent=name.trim().charAt(0).toLocaleUpperCase('kk-KZ')||'О';document.getElementById('topGroup').textContent=state.profile.group||'Білім алушы профилі';document.getElementById('todayLabel').textContent=new Date().toLocaleDateString('kk-KZ',{weekday:'long',day:'numeric',month:'long'});}
function getRecommendation(){const moduleStats=COURSE.map(m=>{const lessons=m.lessons.map(l=>state.results[l.id]).filter(Boolean);const avg=lessons.length?lessons.reduce((n,r)=>n+(r.bestPercent??0),0)/lessons.length:null;const incomplete=m.lessons.filter(l=>!state.results[l.id]?.completed);return {module:m,avg,incomplete};});const low=moduleStats.filter(x=>x.avg!==null&&x.avg<75&&x.incomplete.length).sort((a,b)=>a.avg-b.avg)[0];if(low)return {module:low.module,lesson:low.incomplete[0],reason:`Бұл бөлімдегі тест нәтижелерің шамамен ${Math.round(low.avg)}%. Негізгі ұғымдарды қайталап, біліміңді бекіт.`};const next=moduleStats.find(x=>x.incomplete.length);if(next)return {module:next.module,lesson:next.incomplete[0],reason:'Келесі сабақ осы тақырыпты жүйелі меңгеруге көмектеседі. Сабақты оқып, қысқа тестті орында.'};return {module:COURSE[0],lesson:COURSE[0].lessons[0],reason:`Барлық ${allLessons.length} сабақты аяқтадың! Енді күрделі тақырыптарды қайталап, ойын тесттері арқылы біліміңді бекіт.`};}
function renderDashboard(){renderTopProfile();const completed=totalCompleted();const progress=Math.round(completed/allLessons.length*100);document.getElementById('statLessons').textContent=completed;document.getElementById('statPoints').textContent=state.xp||0;const avg=averageScore();document.getElementById('statAccuracy').textContent=avg===null?'—':avg;document.getElementById('accuracySuffix').textContent=avg===null?'':'%';document.getElementById('statTestCount').textContent=state.attempts.length?`${state.attempts.length} тест әрекеті`:'Әзірге тест тапсырылмады';document.getElementById('statStreak').textContent=state.streak||0;document.getElementById('lessonProgressText').textContent=`${progress}% орындалды`;document.getElementById('lessonProgressBar').style.width=progress+'%';document.getElementById('heroProgress').textContent=progress+'%';const next=allLessons.find(l=>!state.results[l.id]?.completed)||allLessons[0];const res=state.results[next.id];document.getElementById('continueCard').innerHTML=`<div class="course-art art-${next.moduleTone}">${next.moduleIndex===0?'▣':next.moduleIndex===1?'⌘':next.moduleIndex===2?'▤':next.moduleIndex===3?'⌁':next.moduleIndex===4?'▦':next.moduleIndex===5?'⛨':next.moduleIndex===6?'⌁':'▥'}</div><div class="continue-info"><span class="module-subtitle">${escapeHTML(next.moduleShort.toUpperCase())} · ${String(next.number).padStart(2,'0')}</span><strong>${escapeHTML(next.title)}</strong><span class="muted">${escapeHTML(next.summary)}</span><div class="continue-meta"><span>${next.duration} минут</span><span>${res?.completed?'Аяқталған':'Оқу керек'}</span></div></div>`;document.getElementById('continueButton').onclick=()=>openLesson(next.id);const rec=getRecommendation();document.getElementById('recommendationContent').innerHTML=`<div class="recommendation-topic"><div class="recommend-emblem">✦</div><div><strong>${escapeHTML(rec.lesson.title)}</strong><p>${escapeHTML(rec.reason)}</p><div class="recommendation-reason">Ұсыныс себебі: жеке оқу прогресі</div></div></div>`;document.getElementById('recommendButton').onclick=()=>openLesson(rec.lesson.id);document.getElementById('quickPathGrid').innerHTML=COURSE.map((m,i)=>{const done=m.lessons.filter(l=>state.results[l.id]?.completed).length;return `<button class="quick-path-card" data-module-open="${m.id}"><div class="quick-path-top"><span class="quick-path-icon ${toneBg(m.tone)}">${m.icon}</span><span class="muted" style="font-size:9px">${done}/${m.lessons.length}</span></div><strong>${escapeHTML(m.short)}</strong><small>${escapeHTML(m.subtitle)}</small><span class="mini-progress"><span style="width:${done/m.lessons.length*100}%;background:${toneColor(m.tone)}"></span></span></button>`}).join('');document.querySelectorAll('[data-module-open]').forEach(btn=>btn.addEventListener('click',()=>{showPage('course');const card=document.querySelector(`[data-module-id="${btn.dataset.moduleOpen}"]`);if(card){card.classList.add('open');card.scrollIntoView({behavior:'smooth',block:'center'});}}));}
function toneBg(tone){return ({purple:'art-purple',blue:'art-blue',orange:'art-orange',green:'art-green'})[tone]||'art-purple';}
function toneColor(tone){return ({purple:'#9177ed',blue:'#6aa7eb',orange:'#f0ae7d',green:'#63c3a0'})[tone]||'#9177ed';}
function renderCourse(){const completed=totalCompleted(),pct=Math.round(completed/allLessons.length*100);document.getElementById('courseCompleted').textContent=completed;document.getElementById('courseProgressBar').style.width=pct+'%';const query=(document.getElementById('lessonSearch')?.value||'').toLocaleLowerCase('kk-KZ').trim();let html='';COURSE.forEach((m,idx)=>{const lessons=m.lessons.filter(l=>{const hit=!query||`${l.title} ${l.summary} ${m.title}`.toLocaleLowerCase('kk-KZ').includes(query);const done=!!state.results[l.id]?.completed;const filter=currentFilter==='all'||(currentFilter==='complete'&&done)||(currentFilter==='incomplete'&&!done);return hit&&filter;});if(!lessons.length)return;const doneCount=m.lessons.filter(l=>state.results[l.id]?.completed).length;html+=`<article class="module-card" data-module-id="${m.id}"><div class="module-header" role="button" tabindex="0" data-toggle-module="${m.id}"><div class="module-number ${toneBg(m.tone)}" style="color:${toneColor(m.tone)}">${String(idx+1).padStart(2,'0')}</div><div class="module-header-info"><h3>${escapeHTML(m.title)}</h3><p>${escapeHTML(m.description)}</p></div><div class="module-header-meta"><strong>${doneCount}/${m.lessons.length} сабақ</strong><small>${doneCount===m.lessons.length?'Толық аяқталды':m.level}</small></div><span class="module-chevron">⌄</span></div><div class="module-lessons">${lessons.map(l=>{const isDone=!!state.results[l.id]?.completed;return `<button class="lesson-row ${isDone?'done':''}" data-open-lesson="${l.id}"><span class="lesson-check">${isDone?'✓':'↗'}</span><span class="lesson-row-info"><strong>${escapeHTML(l.title)}</strong><small>${escapeHTML(l.summary)} · ${l.duration} мин · тест ${l.quiz.length} сұрақ</small></span><span class="lesson-row-cta">${isDone?'Қайталау':'Сабақты ашу'} →</span></button>`}).join('')}</div></article>`;});document.getElementById('courseModules').innerHTML=html||'<div class="empty-state">Іздеу шарттарына сай сабақ табылмады. Басқа сөзбен іздеп көр.</div>';document.querySelectorAll('[data-toggle-module]').forEach(el=>{const toggle=()=>el.closest('.module-card').classList.toggle('open');el.addEventListener('click',toggle);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle();}})});document.querySelectorAll('[data-open-lesson]').forEach(btn=>btn.addEventListener('click',()=>openLesson(btn.dataset.openLesson)));}
function renderLesson(lesson){
  const module=COURSE[lesson.moduleIndex];const result=state.results[lesson.id];
  const videoUrl=`https://www.youtube.com/results?search_query=${encodeURIComponent(lesson.videoSearch || (lesson.title+' server tutorial'))}`;
  const extra=lesson.extraDetails||[];
  document.getElementById('lessonContent').innerHTML=`
  <div class="lesson-hero"><div class="eyebrow"><span class="eyebrow-line"></span> ${escapeHTML(module.title.toUpperCase())}</div><h1>${escapeHTML(lesson.title)}</h1><p>${escapeHTML(lesson.summary)}</p><div class="lesson-tags"><span class="lesson-tag">${lesson.duration} минут</span><span class="lesson-tag">${lesson.quiz.length} сұрақтық тест</span><span class="lesson-tag">${result?.completed?'✓ Аяқталған':'Жаңа сабақ'}</span><span class="lesson-tag">№ ${lesson.number} / ${allLessons.length}</span></div></div>
  <div class="lesson-layout"><div class="lesson-main">
  <section class="lesson-section"><h2>📘 Негізгі түсінік</h2><div class="definition-box">${escapeHTML(lesson.definition)}</div>${lesson.content.map(p=>`<p>${escapeHTML(p)}</p>`).join('')}<h3>Нені есте сақтау керек?</h3><p>${escapeHTML(lesson.takeaway)}</p></section>
  <section class="lesson-section"><h2>💡 Өмірдегі мысалдар</h2><div class="example-grid">${lesson.examples.map(e=>`<article class="example-card"><span>${e[0]}</span><strong>${escapeHTML(e[1])}</strong><p>${escapeHTML(e[2])}</p></article>`).join('')}</div></section>
  <section class="lesson-section deep-dive-section"><div class="deep-dive-title"><span>🔬</span><div><h2>Тереңдетілген түсіндірме</h2><p>Теорияны кәсіби міндетпен байланыстырып көр</p></div></div><div class="deep-dive-grid"><article class="deep-dive-card"><span class="deep-dive-label">ТЕХНИКАЛЫҚ МӘНІ</span><p>${escapeHTML(extra[0]||lesson.content[0])}</p></article><article class="deep-dive-card"><span class="deep-dive-label">ПРАКТИКАЛЫҚ ЗЕРТХАНА</span><p>${escapeHTML(extra[1]||'Негізгі ұғымды схемаға түсір және мысал келтір.')}</p></article><article class="deep-dive-card"><span class="deep-dive-label">ЖИІ КЕЗДЕСЕТІН ҚАТЕ</span><p>${escapeHTML(extra[2]||'Шешім қабылдар алдында техникалық талаптар мен қауіпсіздікті тексер.')}</p></article></div><div class="lesson-checklist"><strong>Өзіңді тексер:</strong><span>✓ Негізгі терминді өз сөзіңмен түсіндіре аламын</span><span>✓ Оны сервердегі нақты жағдаймен байланыстыра аламын</span><span>✓ Ақау болса, қай метриканы немесе журналды қарайтынымды білемін</span></div></section>
  <section class="lesson-video-panel"><div class="video-symbol">▶</div><div class="video-copy"><span class="deep-dive-label">БЕЙНЕСАБАҚ · ${escapeHTML(module.videoId?'ҰСЫНЫЛҒАН ВИДЕО':'ТАҚЫРЫП БОЙЫНША ІЗДЕУ')}</span><h2>${escapeHTML(module.videoTitle||'Тақырыпқа арналған бейнематериал')}</h2><p>Тақырып: ${escapeHTML(lesson.videoSearch||lesson.title)}. Видео ресурс ретінде берілген; көру алдында мазмұнның осы сабаққа сәйкестігін және авторын тексер.</p>${module.videoId?`<div class="video-embed-wrap"><iframe class="lesson-video-embed" src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(module.videoId)}" title="${escapeHTML(module.videoTitle||lesson.title)}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div>`:''}<a class="button button-primary video-link" href="${videoUrl}" target="_blank" rel="noopener noreferrer">${module.videoId?'Қосымша видео іздеу':'YouTube видеосын таңдау'} <span>↗</span></a></div></section>
  <section class="lesson-section" id="lessonQuizArea"><h2>☑ Өзіңді тексер</h2><p>Әр параграфтан кейін тест орында. Жауап түсіндірмесін қарап, нәтижені жеке прогресіңе сақта.</p><button class="button button-primary" id="startLessonQuiz">Тестті бастау <span>→</span></button>${result?.completed?`<p class="muted" style="margin-top:13px;font-size:10px">Соңғы ең жақсы нәтиже: <strong>${result.bestPercent}%</strong>. Қайталап тест тапсыруға болады.</p>`:''}<div id="lessonQuiz"></div></section>
  </div><aside class="lesson-aside"><div class="lesson-action-card"><h3>Сабақ картасы</h3><div class="lesson-stat"><span>Ұзақтығы</span><strong>${lesson.duration} мин</strong></div><div class="lesson-stat"><span>Тест сұрақтары</span><strong>${lesson.quiz.length}</strong></div><div class="lesson-stat"><span>Статус</span><strong>${result?.completed?'Аяқталған':'Оқылмаған'}</strong></div><div class="mini-progress"><span style="width:${result?.completed?100:0}%"></span></div><button class="button button-soft" id="asideStartQuiz">Тестке өту <span>→</span></button></div><div class="lesson-action-card ai-inline"><div class="mini-orb">✦</div><h3>Түсініксіз жер бар ма?</h3><p>ИИ-ден осы тақырыпты қарапайым тілмен немесе басқа мысалмен түсіндіруді сұра.</p><button class="button button-primary" id="askAIAboutLesson">ИИ-ден сұрау <span>↗</span></button></div><div class="lesson-action-card"><h3>Оқуды тиімді жүргіз</h3><p>Анықтаманы оқы, мысалды қара, бейнесабақты көріп, содан кейін тестті орында.</p></div></aside></div>`;
  document.getElementById('startLessonQuiz').onclick=()=>startLessonQuiz(lesson);
  document.getElementById('asideStartQuiz').onclick=()=>{document.getElementById('lessonQuizArea').scrollIntoView({behavior:'smooth'});startLessonQuiz(lesson);};
  document.getElementById('askAIAboutLesson').onclick=()=>{document.getElementById('chatInput').value=`«${lesson.title}» тақырыбын қарапайым тілмен, тағы бір мысалмен түсіндір. Соңында бір тексеру сұрағын бер.`;showPage('ai');document.getElementById('chatInput').focus();};
}
function startLessonQuiz(lesson){activeQuiz={lessonId:lesson.id,index:0,answers:[],checked:false,correct:0};renderQuizQuestion();document.getElementById('lessonQuiz').scrollIntoView({behavior:'smooth',block:'nearest'});}
function renderQuizQuestion(){const lesson=lessonMap[activeQuiz.lessonId];const q=lesson.quiz[activeQuiz.index];if(!q)return finishLessonQuiz();const selected=activeQuiz.answers[activeQuiz.index];document.getElementById('lessonQuiz').innerHTML=`<div class="quiz-box" style="margin-top:16px;border:1px solid #eeebfa;background:#fcfbff;border-radius:14px;padding:16px"><div style="display:flex;justify-content:space-between;gap:12px;font-size:9px;color:#9788d9;font-weight:800;letter-spacing:.7px;margin-bottom:10px"><span>СҰРАҚ ${activeQuiz.index+1} / ${lesson.quiz.length}</span><span>${activeQuiz.correct} дұрыс жауап</span></div><h3 style="font-size:13px;margin-bottom:13px">${escapeHTML(q.q)}</h3><div style="display:grid;gap:7px">${q.options.map((opt,i)=>`<button class="quiz-option" data-answer="${i}" style="text-align:left;display:flex;gap:9px;align-items:center;border:1px solid ${selected===i?'#a99bf3':'#eeedf5'};background:${selected===i?'#f1edff':'#fff'};color:#646980;border-radius:10px;padding:10px;font-size:10px"><span style="height:24px;width:24px;display:grid;place-items:center;background:#f0edff;color:#8c78db;border-radius:7px;font-weight:800;flex:0 0 auto">${String.fromCharCode(65+i)}</span>${escapeHTML(opt)}</button>`).join('')}</div><div id="quizFeedback" style="font-size:10px;line-height:1.7;margin-top:12px;color:${activeQuiz.checked?(selected===q.a?'#369d7b':'#d06c65'):'#898da1'}">${activeQuiz.checked?`${selected===q.a?'Дұрыс!':'Бұл жолы дұрыс емес.'} ${escapeHTML(q.why)}`:'Жауапты таңдап, тексеру батырмасын бас.'}</div><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:13px">${activeQuiz.checked?`<button class="button button-primary" id="quizNext">${activeQuiz.index===lesson.quiz.length-1?'Нәтижені көру':'Келесі сұрақ'} <span>→</span></button>`:`<button class="button button-primary" id="quizCheck" ${selected===undefined?'disabled':''}>Жауапты тексеру <span>✓</span></button>`}</div></div>`;document.querySelectorAll('[data-answer]').forEach(btn=>btn.onclick=()=>{if(activeQuiz.checked)return;activeQuiz.answers[activeQuiz.index]=Number(btn.dataset.answer);renderQuizQuestion();});const check=document.getElementById('quizCheck');if(check)check.onclick=()=>{const answer=activeQuiz.answers[activeQuiz.index];if(answer===undefined)return;activeQuiz.checked=true;if(answer===q.a)activeQuiz.correct++;renderQuizQuestion();};const next=document.getElementById('quizNext');if(next)next.onclick=()=>{activeQuiz.index++;activeQuiz.checked=false;renderQuizQuestion();};}
function finishLessonQuiz(){const lesson=lessonMap[activeQuiz.lessonId];const correct=activeQuiz.correct;const total=lesson.quiz.length;const percent=Math.round(correct/total*100);const prev=state.results[lesson.id]||{bestPercent:0,points:0,attempts:0,completed:false};const rawPoints=correct*10+(correct===total?10:0);const earned=Math.max(0,rawPoints-(prev.points||0));const wasComplete=!!prev.completed;state.results[lesson.id]={completed:true,bestPercent:Math.max(prev.bestPercent||0,percent),points:Math.max(prev.points||0,rawPoints),attempts:(prev.attempts||0)+1,lastPercent:percent};state.attempts.unshift({lessonId:lesson.id,percent,correct,total,at:new Date().toISOString()});state.attempts=state.attempts.slice(0,150);awardXP(earned);markActivity();addHistory(`Тест: ${lesson.title}`,`${correct}/${total} дұрыс жауап · нәтиже ${percent}%`,earned,'☑');saveState();renderTopProfile();document.getElementById('lessonQuiz').innerHTML=`<div style="margin-top:16px;padding:21px;border:1px solid #e3f3ec;border-radius:15px;background:#f4fcf8;text-align:center"><div style="height:52px;width:52px;border-radius:17px;background:#dff8ed;color:#37aa82;font-size:25px;display:grid;place-items:center;margin:0 auto 12px">${percent>=70?'✓':'↻'}</div><div style="font-size:9px;letter-spacing:1px;font-weight:800;color:#6aa992">ТЕСТ НӘТИЖЕСІ</div><div style="font:800 31px var(--head);margin:3px 0;color:#2e9274">${percent}%</div><p style="font-size:11px;color:#738e86">${correct}/${total} сұрақ дұрыс. ${percent>=80?'Тамаша! Тақырыпты жақсы меңгердің.':percent>=50?'Жақсы бастама! Қате жауаптарды қайта қарап шық.':'Қайта оқып көру пайдалы болады. Қате жауаптар — үйрену мүмкіндігі.'}</p><div style="font-size:10px;color:#5aa88b;margin-bottom:13px">+${earned} XP ${wasComplete&&earned===0?'· бұрын берілген ұпай қайта қосылмайды':''}</div><div style="display:flex;justify-content:center;gap:8px;flex-wrap:wrap"><button class="button button-primary" id="retryQuiz">Қайта тапсыру ↻</button><button class="button button-soft" id="backCourseAfterQuiz">Курсқа оралу →</button></div></div>`;document.getElementById('retryQuiz').onclick=()=>startLessonQuiz(lesson);document.getElementById('backCourseAfterQuiz').onclick=()=>showPage('course');document.getElementById('statLessons')&&(document.getElementById('statLessons').textContent=totalCompleted());activeQuiz=null;renderDashboard();showMotivation(percent, lesson);}
function showMotivation(percent, lesson){
  const modal=document.getElementById('motivationModal');if(!modal)return;
  const phrases=percent>=90?['Керемет нәтиже! Сен теорияны практикамен байланыстырып жатырсың.','Тамаша жұмыс — тұрақты дайындық кәсіби дағдыға айналады.','Сен қиын тақырыпты меңгердің. Енді алған біліміңді практикада қолдан!']:
    percent>=70?['Жақсы жұмыс! Тағы бір қайталау сенімділігіңді арттырады.','Әр қадам маңызды. Қателеріңді талдау — алға жылжудың жолы.','Дұрыс бағыттасың. Келесі сабақта да осы қарқынды сақта!']:
    ['Қате жауап — үйренудің бір бөлігі. Енді қай жерін қайталау керегін білесің.','Бірден бәрін білу міндет емес. Тақырыпты бөліктерге бөліп қайта көр.','Жетістік бір талпыныспен өлшенбейді. Қайталап көруге күшің жетеді!'];
  const phrase=phrases[Math.floor(Math.random()*phrases.length)];
  document.getElementById('motivationPercent').textContent=`${percent}%`;
  document.getElementById('motivationPhrase').textContent=phrase;
  document.getElementById('motivationLessonTitle').textContent=lesson.title;
  modal.classList.add('show');modal.setAttribute('aria-hidden','false');
  document.getElementById('motivationClose').onclick=()=>{modal.classList.remove('show');modal.setAttribute('aria-hidden','true');};
  document.getElementById('motivationContinue').onclick=()=>{modal.classList.remove('show');modal.setAttribute('aria-hidden','true');const next=allLessons.find(l=>!state.results[l.id]?.completed);if(next)openLesson(next.id);else showPage('course');};
  modal.onclick=e=>{if(e.target===modal){modal.classList.remove('show');modal.setAttribute('aria-hidden','true');}};
}
function renderPractice(){document.getElementById('practicePoints').textContent=`${state.xp||0} XP`;const practices=[{icon:'☑',tone:'lavender',title:'Сабақ тесттері',description:'Әр параграфты аяқтаған соң 3 сұраққа жауап бер. Қате жауаптардың түсіндірмесін оқы.',meta:`${allLessons.length} сабақ · ${allLessons.reduce((sum,l)=>sum+l.quiz.length,0)} сұрақ`,cta:'Курсқа өту',action:()=>showPage('course')},{icon:'✧',tone:'peach',title:'ИИ түсіндіруі',description:'Күрделі тақырыпты қарапайым тілмен, мысалмен немесе қадамдық нұсқаулықпен түсіндір.',meta:'Жеке көмекші',cta:'Сұрақ қою',action:()=>showPage('ai')},{icon:'♧',tone:'mint',title:'Терминдерді сәйкестендіру',description:'Сервер терминдерін олардың анықтамаларымен жұптастырып, кәсіби сөздік қорыңды бекіт.',meta:'Мини-ойын · XP',cta:'Ойынға кіру',action:()=>{currentGame='match';showPage('games');}},{icon:'▣',tone:'sky',title:'Флеш-карталар',description:'CPU, RAM, RAID, DNS және тағы басқа тақырыптардың қысқа анықтамаларын қайтала.',meta:'Қайталау режимі',cta:'Қайталауды бастау',action:()=>{currentGame='flash';showPage('games');}},{icon:'↗',tone:'peach',title:'Жылдам сынақ',description:'Аралас сұрақтарға жауап беріп, әртүрлі бөлімдердегі біліміңді байқап көр.',meta:'5 сұрақ · таймерсіз',cta:'Тестті бастау',action:()=>{currentGame='quick';showPage('games');}},{icon:'▥',tone:'lavender',title:'Прогресс талдауы',description:'Қай бөлімдер аяқталғанын, тест нәтижелерін және келесі оқу қадамын қара.',meta:'Жеке статистика',cta:'Есепті ашу',action:()=>showPage('progress')}];document.getElementById('practiceGrid').innerHTML=practices.map((p,i)=>`<article class="practice-card"><span class="practice-icon ${p.tone}">${p.icon}</span><h3>${p.title}</h3><p>${p.description}</p><div class="practice-card-footer"><span>${p.meta}</span><strong>${i+1<10?'0':''}${i+1}</strong></div><button class="button button-soft" data-practice-action="${i}">${p.cta} <span>→</span></button></article>`).join('');document.querySelectorAll('[data-practice-action]').forEach(btn=>btn.onclick=()=>practices[Number(btn.dataset.practiceAction)].action());const rec=getRecommendation();document.getElementById('assignmentText').textContent=`${rec.lesson.title}. ${rec.reason}`;document.getElementById('assignmentButton').onclick=()=>openLesson(rec.lesson.id);}

function renderServerLab(){
  const form=document.getElementById('serverConfigForm');
  const result=document.getElementById('serverConfigResult');
  if(!form||!result)return;
  const data={
    web:{label:'Веб-портал',small:{cpu:'4 vCPU',ram:'8 GB RAM',drive:'500 GB SSD',network:'1 Gbit/s'},medium:{cpu:'8 vCPU',ram:'16–32 GB RAM',drive:'1 TB NVMe SSD',network:'1–10 Gbit/s'},large:{cpu:'16+ vCPU',ram:'32–64 GB RAM',drive:'2 × NVMe SSD',network:'10 Gbit/s и выше'}},
    database:{label:'Деректер базасы',small:{cpu:'4–8 vCPU',ram:'16 GB RAM',drive:'NVMe SSD, мониторинг IOPS',network:'1 Gbit/s'},medium:{cpu:'8–16 vCPU',ram:'32–64 GB RAM',drive:'NVMe SSD + жеке backup',network:'10 Gbit/s қажет болуы мүмкін'},large:{cpu:'16–32+ vCPU',ram:'64–128 GB+ RAM',drive:'Жылдам дискілер, репликация',network:'10–25 Gbit/s, жүктеме тесті'}},
    files:{label:'Файл сервері',small:{cpu:'4 vCPU',ram:'8–16 GB RAM',drive:'2 × HDD/SSD, backup бөлек',network:'1 Gbit/s'},medium:{cpu:'8 vCPU',ram:'16–32 GB RAM',drive:'RAID + бөлек backup сақтау',network:'1–10 Gbit/s'},large:{cpu:'8–16 vCPU',ram:'32–64 GB RAM',drive:'NAS/SAN немесе масштабталатын сақтау',network:'10 Gbit/s, бірнеше жол'}},
    virtual:{label:'Виртуализация',small:{cpu:'8 vCPU',ram:'32 GB RAM',drive:'1–2 TB SSD',network:'1–10 Gbit/s'},medium:{cpu:'16–24 vCPU',ram:'64–128 GB RAM',drive:'NVMe + резервтік қойма',network:'10 Gbit/s'},large:{cpu:'32+ vCPU',ram:'128–512 GB RAM',drive:'Резервтелген кластерлік сақтау',network:'10–25 Gbit/s'}},
    monitoring:{label:'Мониторинг және журналдар',small:{cpu:'2–4 vCPU',ram:'8 GB RAM',drive:'500 GB SSD',network:'1 Gbit/s'},medium:{cpu:'4–8 vCPU',ram:'16–32 GB RAM',drive:'1–2 TB SSD',network:'1–10 Gbit/s'},large:{cpu:'8–16 vCPU',ram:'32–64 GB RAM',drive:'Журналға арналған көлемді сақтау',network:'10 Gbit/s'}}
  };
  const levelLabels={small:'Аз жүктеме',medium:'Орта жүктеме',large:'Жоғары жүктеме'};
  function calculate(){
    const type=document.getElementById('serverWorkload').value;
    const users=document.getElementById('serverUsers').value;
    const storage=document.getElementById('serverStorage').value;
    const availability=document.getElementById('serverAvailability').value;
    const config=data[type][users];
    const storageText=storage==='fast'?'Төмен кідірісті SSD/NVMe, жазу жүктемесі мен диск ресурсын мониторингтеу':storage==='archive'?'Сыйымдылыққа сай HDD/объектілік сақтау және тексерілетін резервтік көшірме':`SSD/NVMe немесе HDD таңдауы нақты оқу/жазу жүктемесіне сай болсын`;
    const fault=availability==='high'?'Екі тәуелсіз қуат көзі мүмкіндігін, мониторингті, резервтік түйінді және қалпына келтіру сынағын жоспарла.':'Жоспарлы тоқтау уақытын анықтап, автоматты backup пен жүйені қалпына келтіру қадамын құжатта.';
    const items=[['⚙️','CPU',config.cpu],['🧠','Жедел жад',config.ram],['💾','Сақтау',config.drive],['🌐','Желі',config.network],['🧰','Дерек саясаты',storageText],['🛡️','Сенімділік',fault]];
    result.innerHTML=`<div class="lab-result-summary"><span class="lab-summary-icon">▣</span><div><span class="deep-dive-label">ОҚУ ҰСЫНЫСЫ</span><h3>${escapeHTML(data[type].label)}</h3><p>${escapeHTML(levelLabels[users])} · ${availability==='high'?'Жоғары қолжетімділік':'Стандартты қолжетімділік'}</p></div></div><div class="lab-result-grid">${items.map(([icon,label,value])=>`<article class="lab-result-item"><span>${icon}</span><div><strong>${escapeHTML(label)}</strong><p>${escapeHTML(value)}</p></div></article>`).join('')}</div><div class="lab-caveat"><strong>Маңызды:</strong> бұл оқу симуляторы және бастапқы баға ғана. Нақты сервер сатып алу алдында шынайы пайдаланушы жүктемесін, өсу жоспарын, өнімділік сынағын және бюджетті есептеу қажет.</div><button class="button button-soft" type="button" id="labAskAI">ИИ-ден таңдалған конфигурацияны түсіндіруді сұрау ↗</button>`;
    document.getElementById('labAskAI')?.addEventListener('click',()=>{const prompt=`Маған ${data[type].label} үшін ${levelLabels[users].toLowerCase()} деңгейінде сервер конфигурациясы ұсынылды: CPU ${config.cpu}, RAM ${config.ram}, сақтау ${config.drive}, желі ${config.network}. Қандай шектеулер бар және қосымша нені тексеруім керек?`;document.getElementById('chatInput').value=prompt;showPage('ai');document.getElementById('chatInput').focus();});
  }
  if(form.dataset.bound!=='true'){form.dataset.bound='true';form.addEventListener('submit',e=>{e.preventDefault();calculate();});['serverWorkload','serverUsers','serverStorage','serverAvailability'].forEach(id=>document.getElementById(id)?.addEventListener('change',calculate));}
  calculate();
}

const MATCH_PAIRS=[{id:'server',term:'Сервер',def:'Клиентке қызмет немесе ресурс ұсынатын жүйе',emoji:'🖥️'},{id:'ram',term:'RAM',def:'Қазіргі жұмыс деректерін уақытша сақтайтын жад',emoji:'🧠'},{id:'dns',term:'DNS',def:'Домен атауын IP мекенжаймен сәйкестендіреді',emoji:'🌐'},{id:'raid',term:'RAID 1',def:'Деректерді айна түрінде бірнеше дискіге сақтайды',emoji:'🪞'},{id:'backup',term:'Backup',def:'Деректі кейін қалпына келтіруге арналған көшірме',emoji:'🧰'},{id:'firewall',term:'Firewall',def:'Желілік трафикті ережелер бойынша сүзеді',emoji:'🧱'}];
const FLASHCARDS=[{term:'Сервер',emoji:'🖥️',definition:'Желіде басқа құрылғыларға қызмет не ресурс ұсынатын компьютер немесе бағдарлама.'},{term:'CPU',emoji:'⚙️',definition:'Нұсқауларды орындап, есептеулерді өңдейтін орталық процессор.'},{term:'RAM',emoji:'🧠',definition:'Қосулы жүйедегі белсенді жұмыс деректерін уақытша ұстайтын жедел жад.'},{term:'SSD',emoji:'⚡',definition:'Деректерді флеш-жадта сақтайтын, қозғалмалы бөлшектері жоқ сақтау құрылғысы.'},{term:'RAID 1',emoji:'🪞',definition:'Деректердің бірдей көшірмесін бірнеше дискіге жазатын айна режимі.'},{term:'DNS',emoji:'🌐',definition:'Домен атаулары мен IP мекенжайлары сияқты жазбаларды сәйкестендіретін жүйе.'},{term:'Гипервизор',emoji:'▦',definition:'Виртуалды машиналарға ресурстар ұсынатын және оларды басқаратын бағдарламалық қабат.'},{term:'Firewall',emoji:'🧱',definition:'Желіге кіретін және шығатын трафикті ережелер бойынша шектейтін қорғаныс құралы.'}];
function shuffle(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function renderGame(){document.querySelectorAll('.game-tab').forEach(t=>t.classList.toggle('active',t.dataset.game===currentGame));document.getElementById('gameLevel').textContent=`${Math.floor((state.xp||0)/100)+1}-деңгей`;if(currentGame==='match')renderMatchGame();else if(currentGame==='flash')renderFlashGame();else renderQuickGame();}
function renderMatchGame(){if(!matchGame){const cards=shuffle(MATCH_PAIRS.flatMap(p=>[{pairId:p.id,type:'term',label:p.term,emoji:p.emoji},{pairId:p.id,type:'def',label:p.def,emoji:'✦'}]));matchGame={cards,selected:[],matched:[],tries:0,finished:false};}const g=matchGame;document.getElementById('gameStage').innerHTML=`<div class="game-stage-head"><div><h2>Терминді анықтамасымен сәйкестендір</h2><p class="muted">Алдымен терминді, содан кейін оған сәйкес анықтаманы бас.</p></div><span class="game-tag">${g.matched.length/2} / ${MATCH_PAIRS.length} жұп</span></div><div class="match-board">${g.cards.map((c,i)=>`<button class="match-card ${g.matched.includes(i)?'matched':''} ${g.selected.includes(i)?'selected':''}" data-match-card="${i}" ${g.matched.includes(i)?'disabled':''}><span class="match-emoji">${g.matched.includes(i)?'✓':g.selected.includes(i)?c.emoji:(c.type==='term'?c.emoji:'❔')}</span><strong>${escapeHTML(g.matched.includes(i)||g.selected.includes(i)?c.label:c.type==='term'?c.label:'Анықтама')}</strong></button>`).join('')}</div><div class="match-feedback" id="matchFeedback">${g.finished?'Керемет! Барлық жұп табылды.':'Дұрыс жұптар табылған сайын карта жасыл түске өзгереді.'}</div><div class="game-controls"><span class="muted">Әрекет саны: ${g.tries}</span><button class="button button-outline" id="resetMatch">Қайта бастау ↻</button></div>`;document.querySelectorAll('[data-match-card]').forEach(btn=>btn.onclick=()=>handleMatch(Number(btn.dataset.matchCard)));document.getElementById('resetMatch').onclick=()=>{matchGame=null;renderMatchGame();};}
function handleMatch(idx){const g=matchGame;if(g.selected.includes(idx)||g.matched.includes(idx)||g.selected.length>=2)return;g.selected.push(idx);if(g.selected.length===2){g.tries++;const [a,b]=g.selected.map(i=>g.cards[i]);if(a.pairId===b.pairId&&a.type!==b.type){g.matched.push(...g.selected);g.selected=[];document.getElementById('matchFeedback').textContent='Дұрыс жұп! Келесі сәйкестікті тап.';if(g.matched.length===g.cards.length){g.finished=true;awardGameReward('match',25,'Сәйкестендіру ойыны аяқталды','Барлық 6 жұп табылды.','♧');document.getElementById('matchFeedback').textContent='Керемет! Барлық жұп табылды. +25 XP (бүгінгі марапат)';}}else{document.getElementById('matchFeedback').textContent='Бұл жұп сәйкес келмейді. Термин мен анықтаманы қайта ойлап көр.';renderMatchGame();const feedback=document.getElementById('matchFeedback');if(feedback)feedback.textContent='Бұл жұп сәйкес келмейді. Таңдауды өзгерту үшін бос карта бас.';g.selected=[Number(idx),g.selected[0]];setTimeout(()=>{g.selected=[];renderMatchGame();},700);return;}}renderMatchGame();}
function renderFlashGame(){const card=FLASHCARDS[flashIndex];document.getElementById('gameStage').innerHTML=`<div class="game-stage-head"><div><h2>Флеш-карталар</h2><p class="muted">Терминді еске түсіріп, картаны басып анықтамасын аш.</p></div><span class="game-tag">${flashIndex+1} / ${FLASHCARDS.length}</span></div><div class="flashcard-wrap"><button class="flashcard" id="flipFlash"><span class="flash-emoji">${flashRevealed?'💡':card.emoji}</span><strong>${escapeHTML(card.term)}</strong>${flashRevealed?`<p>${escapeHTML(card.definition)}</p>`:'<p>Бұл термин нені білдіреді?</p>'}<small>${flashRevealed?'Келесі картаны ашу үшін төмендегі батырманы бас':'Картаны аудару үшін бас'}</small></button></div><div class="flash-progress">${FLASHCARDS.map((_,i)=>`<span class="${i===flashIndex?'active':''}"></span>`).join('')}</div><div class="game-controls"><button class="button button-outline" id="flashPrev">← Алдыңғы</button><button class="button button-soft" id="flashReveal">${flashRevealed?'Түсіндім':'Жауабын көрсету'} <span>↻</span></button><button class="button button-primary" id="flashNext">Келесі →</button></div>`;document.getElementById('flipFlash').onclick=()=>{flashRevealed=!flashRevealed;renderFlashGame();};document.getElementById('flashReveal').onclick=()=>{flashRevealed=!flashRevealed;renderFlashGame();};document.getElementById('flashPrev').onclick=()=>{flashIndex=(flashIndex+FLASHCARDS.length-1)%FLASHCARDS.length;flashRevealed=false;renderFlashGame();};document.getElementById('flashNext').onclick=()=>{flashIndex=(flashIndex+1)%FLASHCARDS.length;flashRevealed=false;if(flashIndex===0)awardGameReward('flash',10,'Флеш-карталар қайталанды','8 терминді қарадың.','▣');renderFlashGame();};}
function buildQuickQuestionPool(){return shuffle(allLessons.flatMap(l=>l.quiz.map(q=>({...q,lessonId:l.id,lessonTitle:l.title})))).slice(0,5);}
function renderQuickGame(){if(!quickGame)quickGame={questions:buildQuickQuestionPool(),index:0,score:0,selected:null,checked:false,done:false};const g=quickGame;if(g.done){document.getElementById('gameStage').innerHTML=`<div style="text-align:center;padding:35px 8px"><div style="font-size:35px;color:#846de5">✦</div><h2 style="margin:12px 0">Жылдам тест аяқталды!</h2><p class="muted" style="font-size:11px">${g.score}/5 дұрыс жауап · ${Math.round(g.score/5*100)}% нәтиже</p><div style="font:800 24px var(--head);color:#745add;margin:10px 0">${g.score*8} XP</div><button class="button button-primary" id="restartQuick">Қайта ойнау ↻</button></div>`;document.getElementById('restartQuick').onclick=()=>{quickGame=null;renderQuickGame();};return;}const q=g.questions[g.index];document.getElementById('gameStage').innerHTML=`<div class="game-stage-head"><div><h2>Жылдам білім сынағы</h2><p class="muted">Әртүрлі бөлімдерден кездейсоқ сұрақтар.</p></div><span class="game-tag">${g.index+1} / 5 сұрақ</span></div><div class="quick-question"><span class="quick-question-count">СҰРАҚ ${g.index+1} · ${escapeHTML(q.lessonTitle.toUpperCase())}</span><h3>${escapeHTML(q.q)}</h3><div class="quick-options">${q.options.map((op,i)=>`<button class="quick-option ${g.checked&&i===q.a?'correct':''} ${g.checked&&i===g.selected&&i!==q.a?'wrong':''}" data-quick-answer="${i}" ${g.checked?'disabled':''}><span class="option-key">${String.fromCharCode(65+i)}</span>${escapeHTML(op)}</button>`).join('')}</div><div id="quickFeedback" style="font-size:10px;line-height:1.7;margin-top:13px;color:${g.checked?(g.selected===q.a?'#3da581':'#d27871'):'#969aae'}">${g.checked?`${g.selected===q.a?'Дұрыс жауап!':'Дұрыс жауап: '+q.options[q.a]+'.'} ${escapeHTML(q.why)}`:'Бір нұсқаны таңда.'}</div><div style="display:flex;justify-content:flex-end;margin-top:17px">${g.checked?`<button class="button button-primary" id="quickNext">${g.index===4?'Нәтижені көру':'Келесі сұрақ'} →</button>`:`<button class="button button-primary" id="quickCheck" ${g.selected===null?'disabled':''}>Тексеру ✓</button>`}</div></div>`;document.querySelectorAll('[data-quick-answer]').forEach(btn=>btn.onclick=()=>{if(g.checked)return;g.selected=Number(btn.dataset.quickAnswer);renderQuickGame();});const check=document.getElementById('quickCheck');if(check)check.onclick=()=>{g.checked=true;if(g.selected===q.a)g.score++;renderQuickGame();};const next=document.getElementById('quickNext');if(next)next.onclick=()=>{g.index++;g.selected=null;g.checked=false;if(g.index>=5){g.done=true;awardGameReward('quick',g.score*8,'Жылдам тест аяқталды',`${g.score}/5 дұрыс жауап.`,'☑');}renderQuickGame();};}
function awardGameReward(game,points,title,detail,icon){const day=todayISO();if(state.gameRewardDays[game]===day){return 0;}state.gameRewardDays[game]=day;awardXP(points);markActivity();addHistory(title,detail,points,icon);saveState();return points;}
function renderProgress(){const completed=totalCompleted(),pct=Math.round(completed/allLessons.length*100),avg=averageScore();document.getElementById('mainProgressNum').textContent=pct+'%';document.getElementById('mainProgressRing').style.background=`conic-gradient(#b7f0e9 ${pct*3.6}deg,#ffffff30 ${pct*3.6}deg)`;document.getElementById('progressLessons').textContent=completed;document.getElementById('progressXP').textContent=`${state.xp||0} XP`;document.getElementById('progressAccuracy').textContent=avg===null?'—':avg+'%';document.getElementById('progressTestCount').textContent=state.attempts.length?`${state.attempts.length} әрекет`:'Тест нәтижесі жоқ';document.getElementById('progressModules').innerHTML=COURSE.map(m=>{const done=m.lessons.filter(l=>state.results[l.id]?.completed).length;const score=m.lessons.map(l=>state.results[l.id]?.bestPercent).filter(v=>v!==undefined);const color=toneColor(m.tone);return `<div class="module-progress-row"><span class="module-progress-name">${escapeHTML(m.short)}</span><span class="mini-progress"><span style="width:${done/m.lessons.length*100}%;background:${color}"></span></span><small>${done}/${m.lessons.length}</small></div>`}).join('');const achievements=[{icon:'✧',title:'Алғашқы қадам',desc:'1 сабақ аяқта',ok:completed>=1},{icon:'☑',title:'Тест шебері',desc:'5 тест әрекеті',ok:state.attempts.length>=5},{icon:'▤',title:'Білім жинаушы',desc:'8 сабақ аяқта',ok:completed>=8},{icon:'♧',title:'Курс зерттеушісі',desc:`${allLessons.length} сабақты аяқта`,ok:completed===allLessons.length}];document.getElementById('achievementsList').innerHTML=achievements.map(a=>`<div class="achievement ${a.ok?'':'locked'}"><span class="achievement-icon">${a.ok?'✓':a.icon}</span><div><strong>${a.title}</strong><small>${a.ok?'Құттықтаймыз!':a.desc}</small></div></div>`).join('');document.getElementById('activityHistory').innerHTML=state.history.length?state.history.slice(0,8).map(h=>`<div class="activity-row"><span class="activity-icon">${escapeHTML(h.icon)}</span><div><strong>${escapeHTML(h.title)}</strong><small>${escapeHTML(h.detail)} · ${new Date(h.at).toLocaleString('kk-KZ',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</small></div>${h.points?`<span class="activity-xp">+${h.points} XP</span>`:''}</div>`).join(''):'<div class="empty-state">Әзірге әрекет жоқ. Бір сабақты ашып, тест тапсырып көр.</div>';}
function renderAccount(){document.getElementById('accountNameDisplay').textContent=displayName();document.getElementById('accountGroupDisplay').textContent=state.profile.group||'Білім алушы профилі';document.getElementById('accountAvatar').textContent=displayName().trim().charAt(0).toLocaleUpperCase('kk-KZ')||'О';document.getElementById('accountLevel').textContent=`${Math.floor((state.xp||0)/100)+1}-деңгей`;document.getElementById('accountLevelTitle').textContent=(state.xp||0)>=500?'Сервер сарапшысы':(state.xp||0)>=200?'Білім зерттеушісі':'Оқу зерттеушісі';document.getElementById('accountLessons').textContent=totalCompleted();document.getElementById('accountXp').textContent=state.xp||0;document.getElementById('accountTests').textContent=state.attempts.length;document.getElementById('profileName').value=state.profile.name==='Білім алушы'?'':state.profile.name;document.getElementById('profileGroup').value=state.profile.group||'';document.getElementById('profileGoal').value=state.profile.goal||'basics';}
function buildLocalAIReply(question){const q=question.toLocaleLowerCase('kk-KZ');const rec=getRecommendation();const match=allLessons.find(l=>q.includes(l.title.toLocaleLowerCase('kk-KZ'))||l.title.toLocaleLowerCase('kk-KZ').split(/[ ()—,]/).some(w=>w.length>4&&q.includes(w)));if(q.includes('прогресс')||q.includes('прогрес')||q.includes('ұсыныс')||q.includes('қай тақырып')){const weak=COURSE.map(m=>({m,items:m.lessons.map(l=>state.results[l.id]?.bestPercent).filter(x=>x!==undefined)})).filter(x=>x.items.length).map(x=>({...x,avg:x.items.reduce((a,b)=>a+b,0)/x.items.length})).sort((a,b)=>a.avg-b.avg)[0];return `Сенің қазіргі прогресің: ${totalCompleted()}/${allLessons.length} сабақ (${Math.round(totalCompleted()/allLessons.length*100)}%), ${state.xp||0} XP. ${weak?`Ең көп қайталау керек бөлім — «${weak.m.short}»: орташа тест нәтижесі ${Math.round(weak.avg)}%.`:`Әзірге тест нәтижелері аз. Бір сабақтан бастаған дұрыс.`} Менің келесі ұсынысым: «${rec.lesson.title}». ${rec.reason}`;}
 if(q.includes('салыстыр')||q.includes('айырмашылық')||q.includes('айырмашылы')){if(q.includes('ram')&&q.includes('ssd'))return 'RAM мен SSD айырмашылығы: RAM — дәл қазір ашық тұрған бағдарламалар қолданатын жылдам уақытша жұмыс кеңістігі; қуат өшсе, ондағы дерек сақталмайды. SSD — файлдар мен бағдарламаларды ұзақ мерзімге сақтайтын құрылғы. Мысал: үстел үстіндегі ашық құжаттар — RAM, шкафқа салып қойған құжаттар — SSD. Серверге екеуі де керек, бірақ міндеттері бөлек.';if(q.includes('raid'))return 'RAID 1 деректерді айна түрінде екі не одан көп дискке жазады. RAID 5 деректер блоктары мен паритет ақпаратын бірнеше дискіге таратып, бір диск ақауына төзе алады. RAID 1 түсінікті әрі қалпына келтіруі оңай болуы мүмкін; RAID 5 сыйымдылықты тиімдірек қолдануы мүмкін. Екеуі де резервтік көшірмені алмастырмайды.';if(q.includes('vm')||q.includes('виртуалды')||q.includes('контейнер'))return 'Виртуалды машина — жеке қонақ операциялық жүйесі бар виртуалды компьютерге ұқсайды. Контейнер қосымшаны тәуелділіктерімен бірге оқшаулап іске қосады және көп жағдайда хост ядросын ортақ пайдаланады. VM толық ОС керек кезде ыңғайлы; контейнер қосымшаны жеңіл әрі қайталанатын түрде жеткізуге көмектеседі.';}
 if(q.includes('сервер')||q.includes('server'))return 'Сервер — желідегі басқа компьютерлерге қызмет көрсететін жүйе. Мысалы, браузер сайт сұрағанда веб-сервер оған беттің мазмұнын қайтарады. Оны мейрамханаға ұқсатуға болады: клиент тапсырыс береді, ал сервер сұрауды өңдеп, керек нәтижені ұсынады. Есте сақта: сервердің басты белгісі — қызмет атқаруы, міндетті түрде үлкен компьютер болуы емес.';
 if(q.includes('ram')||q.includes('жедел жад'))return 'RAM — компьютердің қысқа мерзімді жұмыс үстелі сияқты: процессор дәл қазір қолданатын деректерді уақытша ұстайды. Ашық қосымшалар мен сервер процестері RAM пайдаланады. Ал орын жеткіліксіз болса, жүйе баяулауы мүмкін. RAM қуат өшкенде мазмұнын жоғалтады; маңызды файлдарды SSD/HDD және backup сияқты тұрақты сақтау жүйесіне орналастырады.';
 if(q.includes('cpu')||q.includes('процессор'))return 'CPU — сервердің есептеулерді орындайтын бөлігі. Оны тапсырмаларды өңдейтін жұмысшы топ ретінде елестет: ядро саны көп болса, параллель орындалатын кейбір жұмыстарға көмектеседі. Бірақ өнімділік тек ядроға емес, архитектураға, кэшке және бағдарламаның сипатына да байланысты.';
 if(q.includes('raid'))return 'RAID — бірнеше дискіні бір жүйе ретінде ұйымдастыру тәсілі. RAID 0 өнімділікті арттыруы мүмкін, бірақ диск істен шықса дерек тәуекелі жоғары. RAID 1 көшірмені айна түрінде сақтайды. RAID 5 паритет ақпаратын қолданады. Маңыздысы: RAID ақауға төзімділіктің кей түрін береді, бірақ резервтік көшірменің орнына жүрмейді.';
 if(q.includes('dns'))return 'DNS-ті интернеттің атаулар анықтамалығы деп елестет. Адамға сайттың атауын есте сақтау оңай, ал желідегі байланысқа IP мекенжай қажет. DNS домен атауына сәйкес жазбаны тауып береді. Ал DHCP құрылғы желіге қосылғанда IP және басқа баптауларды автоматты бере алады.';
 if(q.includes('виртуал')||q.includes('гипервизор'))return 'Виртуализация бір физикалық сервердің ресурстарында бірнеше виртуалды машинаны іске қосуға мүмкіндік береді. Гипервизор әр виртуалды машинаға CPU, RAM, диск және желі ресурстарын береді. Бұл жабдықты тиімді пайдалануға көмектеседі, бірақ виртуалды машиналар физикалық сервер ресурстарын бөлісетінін ұмытпа.';
 if(q.includes('қауіпсіз')||q.includes('құпиясөз')||q.includes('mfa'))return 'Сервер қауіпсіздігінің қарапайым үш қадамы: әр адамға жеке аккаунт беру, тек міндетіне керек құқықтарды ғана ашу және маңызды есептік жазбаларда MFA қолдану. Жүйені уақытында жаңартып, қажет емес порттарды жауып, журналдарды қарап отыр. Өндірістік серверде өзгерісті алдымен сынақта тексерген дұрыс.';
 if(q.includes('backup')||q.includes('резерв')||q.includes('көшірме'))return 'Резервтік көшірме — бастапқы файл бүлінсе не жоғалса, қалпына келтіруге арналған бөлек сақталған дерек. 3-2-1 қағидасын есте сақта: үш көшірме, екі түрлі тасымалдағыш, бір көшірме бөлек жерде. Ең маңыздысы — backup барын тексерумен шектелмей, қалпына келтіруді сынау.';
 if(q.includes('тест')||q.includes('үй тапсыр')||q.includes('тапсырма'))return `Жеке ұсынысым: «${rec.lesson.title}». ${rec.reason} Сабақты оқып, тестте алдымен өзің жауап бер; содан кейін түсіндірмелерден нені шатастырғаныңды байқа.`;
 if(match)return `Бұл тақырыпты осылай қарастыруға болады: ${match.definition} ${match.content[0]} Практикалық мысал: ${match.examples[0][1]} — ${match.examples[0][2]} Қаласаң, осы сабақтың тестін өтіп, түсінгеніңді тексере аласың.`;
 return `Сұрағыңды бірге талдайық. «${question}» тақырыбын түсіну үшін алдымен негізгі терминді анықтап, оны нақты сервер мысалымен байланыстырып көрейік. Мысалы, серверлік жүйені төрт бөлікпен талдауға болады: есептеу (CPU/RAM), деректер сақтау (SSD/RAID), желі (Ethernet/DNS) және қауіпсіздік (рұқсат, жаңарту, backup). Сұрақты сәл нақтылап немесе термин атауын жазсаң, оны қарапайым қадамдарға бөліп түсіндіремін.`;
}
function addChatMessage(role,text){const messages=document.getElementById('chatMessages');const row=document.createElement('div');row.className=`message-row ${role==='user'?'user-row':'assistant-row'}`;const av=document.createElement('div');av.className='message-avatar';av.textContent=role==='user'?(displayName().charAt(0)||'О'):'✦';const bubble=document.createElement('div');bubble.className='message-bubble';if(role==='assistant'){const author=document.createElement('div');author.className='message-author';author.textContent='ServerLab AI';const dot=document.createElement('span');dot.className='tiny-online';author.appendChild(dot);bubble.appendChild(author);}const p=document.createElement('p');p.textContent=text;bubble.appendChild(p);row.append(av,bubble);messages.appendChild(row);messages.scrollTop=messages.scrollHeight;return row;}
async function sendChatMessage(text){if(chatBusy)return;const cleaned=text.trim();if(!cleaned)return;addChatMessage('user',cleaned);document.getElementById('chatInput').value='';chatBusy=true;const messages=document.getElementById('chatMessages');const typing=document.createElement('div');typing.className='typing-indicator';typing.textContent='ServerLab AI жауап дайындап жатыр…';typing.id='typingIndicator';messages.appendChild(typing);messages.scrollTop=messages.scrollHeight;let reply='';try{const res=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:cleaned,student:{name:displayName(),completedLessons:totalCompleted(),totalLessons:allLessons.length,experience:state.xp,averageTestScore:averageScore(),recommendation:getRecommendation().lesson.title}})});if(!res.ok)throw new Error('API unavailable');const data=await res.json();reply=data.reply||'';if(data.mode==='openai'){document.getElementById('aiModeLabel').textContent='Генеративті ИИ қосылған';document.getElementById('aiDisclaimer').textContent='Жауап сервер арқылы қосылған ИИ моделінен алынды. Маңызды техникалық және қауіпсіздік ақпаратын тексеріп қолдан.';}}catch{const hadLiveAI=document.getElementById('aiModeLabel').textContent.includes('Генеративті');reply=buildLocalAIReply(cleaned);if(hadLiveAI){document.getElementById('aiModeLabel').textContent='Демо режимі';document.getElementById('aiDisclaimer').textContent='ИИ API уақытша қолжетімсіз болды. Бұл жауап демонстрациялық оқу базасынан берілді; техникалық мәліметтерді тексеріп қолдан.';}}finally{document.getElementById('typingIndicator')?.remove();chatBusy=false;}addChatMessage('assistant',reply);}
async function detectAIMode(){try{const r=await fetch('/api/status');if(!r.ok)return;const data=await r.json();if(data.aiEnabled){document.getElementById('aiModeLabel').textContent='Генеративті ИИ қосылған';document.getElementById('aiDisclaimer').textContent='Жауап сервер арқылы ИИ моделінен алынады. Маңызды ақпаратты оқулықпен немесе ресми құжаттамамен тексер.';}else{document.getElementById('aiModeLabel').textContent='Демо режимі';}}catch{/* Opened as a static page: stay in demo mode. */}}
function exportProgress(){const report={project:'ServerLab AI',generatedAt:new Date().toISOString(),profile:{name:state.profile.name,group:state.profile.group,goal:state.profile.goal},summary:{completedLessons:totalCompleted(),totalLessons:allLessons.length,percent:Math.round(totalCompleted()/allLessons.length*100),xp:state.xp,averageTestScore:averageScore(),testAttempts:state.attempts.length},modules:COURSE.map(m=>({title:m.title,lessons:m.lessons.map(l=>({title:l.title,completed:!!state.results[l.id]?.completed,bestPercent:state.results[l.id]?.bestPercent??null,attempts:state.results[l.id]?.attempts??0}))})),history:state.history};const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='serverlab-ai-progress.json';a.click();URL.revokeObjectURL(url);toast('Прогресс есебі жүктеуге дайын.');}

// Main interface events

document.querySelectorAll('[data-page]').forEach(btn=>btn.addEventListener('click',()=>showPage(btn.dataset.page)));
document.getElementById('mobileMenu').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
document.getElementById('lessonSearch').addEventListener('input',()=>renderCourse());
document.querySelectorAll('.filter-chip').forEach(btn=>btn.addEventListener('click',()=>{currentFilter=btn.dataset.filter;document.querySelectorAll('.filter-chip').forEach(b=>b.classList.toggle('active',b===btn));renderCourse();}));
document.getElementById('backToCourse').addEventListener('click',()=>showPage('course'));
document.querySelectorAll('.game-tab').forEach(btn=>btn.addEventListener('click',()=>{currentGame=btn.dataset.game;matchGame=null;quickGame=null;flashRevealed=false;renderGame();}));
document.getElementById('chatForm').addEventListener('submit',e=>{e.preventDefault();sendChatMessage(document.getElementById('chatInput').value);});
document.querySelectorAll('[data-prompt]').forEach(btn=>btn.addEventListener('click',()=>{document.getElementById('chatInput').value=btn.dataset.prompt;document.getElementById('chatInput').focus();}));
document.getElementById('clearChat').addEventListener('click',()=>{document.getElementById('chatMessages').innerHTML='<div class="chat-day-label">БҮГІН</div><div class="message-row assistant-row"><div class="message-avatar">✦</div><div class="message-bubble"><div class="message-author">ServerLab AI</div><p>Чат тазартылды. Қандай тақырыпты қарастырамыз?</p></div></div>';});
document.getElementById('profileForm').addEventListener('submit',e=>{e.preventDefault();const name=document.getElementById('profileName').value.trim();if(!name){toast('Атыңды енгіз.');return;}state.profile.name=name;state.profile.group=document.getElementById('profileGroup').value.trim();state.profile.goal=document.getElementById('profileGoal').value;saveState();renderTopProfile();renderAccount();renderDashboard();document.getElementById('profileSaveMessage').textContent='Профиль сақталды ✓';toast('Профиль жаңартылды.');});
document.getElementById('exportProgress').addEventListener('click',exportProgress);
document.getElementById('resetProgress').addEventListener('click',()=>{if(!confirm('Барлық сабақ нәтижесін, ұпайды және тарихты осы браузерден тазартқың келе ме? Бұл әрекет қайтарылмайды.'))return;const profile={...state.profile};state=defaultState();state.profile=profile;saveState();renderProgress();renderDashboard();renderCourse();toast('Оқу прогресі тазартылды.');});
document.getElementById('themeButton').addEventListener('click',()=>{document.body.classList.toggle('dark');state.theme=document.body.classList.contains('dark')?'dark':'light';saveState();});
document.getElementById('notificationButton').addEventListener('click',()=>toast(`Келесі оқу ұсынысы: ${getRecommendation().lesson.title}`));

if(state.theme==='dark')document.body.classList.add('dark');renderTopProfile();renderDashboard();renderCourse();renderPractice();renderGame();renderProgress();renderAccount();detectAIMode();

// Auth integration bridge: auth.js can replace/restore the learner state after server login.
window.ServerLabApp = {
  getState(){ return JSON.parse(JSON.stringify(state)); },
  defaultState(){ return defaultState(); },
  getLessons(){ return allLessons.map(l => ({id:l.id,title:l.title,moduleTitle:l.moduleTitle,number:l.number})); },
  setState(incoming){
    const base = defaultState();
    const parsed = incoming && typeof incoming === 'object' ? incoming : {};
    state = { ...base, ...parsed,
      profile: { ...base.profile, ...(parsed.profile || {}) },
      results: parsed.results && typeof parsed.results === 'object' ? parsed.results : {},
      attempts: Array.isArray(parsed.attempts) ? parsed.attempts : [],
      history: Array.isArray(parsed.history) ? parsed.history : [],
      gameRewardDays: parsed.gameRewardDays && typeof parsed.gameRewardDays === 'object' ? parsed.gameRewardDays : {}
    };
    if(state.theme==='dark') document.body.classList.add('dark'); else document.body.classList.remove('dark');
    renderTopProfile(); renderDashboard(); renderCourse(); renderPractice(); renderGame(); renderProgress(); renderAccount();
    saveState();
  }
};
